import {labReport as report} from './benchmark-data.js';
import {libraryChecks} from './library-data.js';
import {submissionProfile} from './runtime-config.js';
import {icon, escapeHTML as esc} from './ui.js';
const runtimes={cpython:'CPython 3.12.3',codon:'Codon 0.20.3',cpp:'C++ · g++ 13.3'};
const algorithms={greedy:'Greedy',minimax:'Minimax · depth 3',mc:'Monte Carlo · 128 rollouts'};
const num=value=>value.toLocaleString('vi-VN',{minimumFractionDigits:3,maximumFractionDigits:3});
const metric=(title,value,note)=>`<div class="bench-metric"><span>${title}</span><strong>${value}</strong><small>${note}</small></div>`;
export function benchmark(state){
  const runtime=state.benchmarkRuntime||'cpp',algorithm=state.benchmarkAlgorithm||'minimax';
  const timing=report.timing[runtime][algorithm], wall=timing.roundtrip_ms;
  return `<div class="page-heading"><div><div class="eyebrow">ĐO LƯỜNG / CẢI THIỆN / THỬ LẠI</div><h1>Test & benchmark</h1><p>Biết bot đang tốn thời gian ở đâu, trước khi bước vào trận đấu.</p></div><a class="btn" href="#/submissions">${icon('upload')}Quản lý phiên bản</a></div>
  <div class="bench-banner">${icon('info')}<div><strong>Báo cáo thật từ thí nghiệm nội bộ · Chưa kết nối worker server</strong><p>Bot nối 5 trên laptop WSL, không phải bot của đội hoặc engine OTTv2. Các số đo dưới đây dùng để xem trước cách đọc kết quả.</p></div></div>
  <div class="bench-layout"><div class="content-stack"><section class="panel bench-card"><div class="bench-section-title"><div><div class="eyebrow">01 / PHIÊN BẢN CỦA ĐỘI</div><h2>Kiểm tra trước khi thi đấu</h2></div><span class="badge">Chờ backend</span></div>
  <label class="field"><span>Phiên bản cần test</span><select class="select" id="benchmark-submission">${state.submissions.map(s=>`<option value="${esc(s.id)}" ${state.benchmarkSubmission===s.id?'selected':''}>${esc(s.version)} · ${submissionProfile(s).label} · ${esc(s.id)}</option>`).join('')}</select></label>
  <ol class="bench-steps"><li><b>1</b><span>Build & thư viện<small>Kiểm tra runtime, API và log biên dịch</small></span></li><li><b>2</b><span>Protocol & luật<small>JSON hợp lệ, nước đi hợp lệ, không crash</small></span></li><li><b>3</b><span>Đo hiệu năng<small>Cùng máy, cùng bộ test, nhiều lần lặp</small></span></li></ol>
  <div class="bench-submit"><button class="btn primary" disabled>Chạy test trên server</button><p>Chưa có worker thực thi source. Chọn phiên bản chưa tạo ra số đo hoặc chứng nhận hợp lệ.</p></div></section>
  <section class="panel bench-card"><div class="bench-section-title"><div><div class="eyebrow">02 / BÁO CÁO THAM KHẢO</div><h2>Chi phí cho một nước đi</h2></div><span class="badge success">Đã đo · Lab</span></div>
  <div class="bench-controls"><label class="field"><span>Runtime</span><select class="select" id="benchmark-runtime">${Object.entries(runtimes).map(([id,label])=>`<option value="${id}" ${runtime===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field"><span>Thuật toán của bot mẫu</span><select class="select" id="benchmark-algorithm">${Object.entries(algorithms).map(([id,label])=>`<option value="${id}" ${algorithm===id?'selected':''}>${label}</option>`).join('')}</select></label></div>
  <div class="bench-metrics">${metric('TRUNG VỊ',num(wall.median_ms)+' ms','50% mẫu trả lời nhanh hơn')}${metric('P95',num(wall.p95_ms)+' ms','95% mẫu không vượt mức này')}${metric('CHẬM NHẤT',num(wall.max_ms)+' ms',wall.samples+' mẫu đo thực tế')}${metric('PEAK RSS',num(report.memory[runtime].peak_rss_mib)+' MiB','Cả tiến trình, qua 3 thuật toán')}</div>
  <p class="bench-caption">Thời gian do runner đo từ gửi observation đến nhận action qua pipe, gồm parse/serialize. Bot giữ sống giữa các lượt. Đây là wall time, chưa đo CPU time.</p>
  <div class="bench-comparison"><h3>Cùng thuật toán, cùng bộ test</h3>${Object.entries(runtimes).map(([id,label])=>{const ms=report.timing[id][algorithm].roundtrip_ms.median_ms;const max=Math.max(...Object.keys(runtimes).map(k=>report.timing[k][algorithm].roundtrip_ms.median_ms));return `<div class="bench-bar-row"><span>${label}</span><div class="bench-bar-track"><i style="width:${Math.max(1,ms/max*100)}%"></i></div><strong>${num(ms)} ms</strong></div>`;}).join('')}</div>
  <div class="bench-details"><div><span>Tính toán trong bot · median</span><strong>${num(timing.compute_ms.median_ms)} ms</strong></div><div><span>Khởi động · median / 20 lần</span><strong>${num(report.startup[runtime].median_ms)} ms</strong></div><div><span>Biên dịch trước khi chạy</span><strong>${runtime==='cpython'?'Không AOT':num(report.build[runtime].seconds)+' s'}</strong></div></div>
  <p class="bench-caption">Khởi động được đo với cache đã ấm. Thời gian build không cộng vào mỗi nước đi. Không dùng số đo laptop để suy ra ngân sách server.</p>
  <div class="bench-result-line">${icon('check')}87/87 trường hợp cho cùng nước đi, điểm và số nút giữa ba runtime.</div><div class="bench-checks"><span>Timeout <b>0</b></span><span>Crash <b>0</b></span><span>Sai khác kết quả <b>0</b></span><span>Luật OTTv2 <b>Chưa test</b></span></div>
  <div class="bench-footer"><span>LAB-20261010-01 · 10/10/2026</span><button class="btn small" data-action="benchmark-export">${icon('download')}Tải báo cáo JSON</button></div></section>
  <section class="panel bench-card"><div class="bench-section-title"><div><div class="eyebrow">03 / THƯ VIỆN THUẬT TOÁN</div><h2>Đã thử với Codon ${esc(libraryChecks.compiler)}</h2></div></div><p>Mỗi dòng là một ví dụ đã compile và đối chiếu output với CPython. Kết quả chỉ áp dụng cho các API được thử bên dưới.</p><div class="table-wrap bench-libraries"><table><thead><tr><th>API / THƯ VIỆN</th><th>KẾT QUẢ</th><th>PHẠM VI ĐÃ THỬ</th></tr></thead><tbody>${libraryChecks.rows.map(row=>`<tr><td><strong>${esc(row.label)}</strong></td><td><span class="badge ${row.passed?'success':''}">${row.passed?'Native · cùng output':'Build fail'}</span></td><td>${esc(row.note)}</td></tr>`).join('')}</tbody></table></div><p class="bench-caption">Thư viện PyPI ngoài bảng chưa được kiểm tra. Cầu nối Python có thể gọi thư viện Python nhưng phần đó vẫn dùng CPython. Các API và kiểu dữ liệu cần kiểm tra theo từng bot.</p><a class="text-link" href="https://docs.exaloop.io/libraries/stdlib/" target="_blank" rel="noopener">Tài liệu thư viện Codon ${icon('arrow')}</a></section></div>
  <aside class="content-stack"><section class="bench-profile"><div class="eyebrow">ĐIỀU KIỆN ĐO</div><h3>So sánh có ngữ cảnh.</h3><dl><dt>CPU</dt><dd>Intel Core i5-13420H</dd><dt>Môi trường</dt><dd>Ubuntu · WSL2 · Linux x86_64</dd><dt>Tài nguyên</dt><dd>Ghim 1 CPU logic · 1 bot mỗi lần</dd><dt>Bộ test</dt><dd>24 vị trí × 5 lần lặp / thuật toán</dd><dt>Game</dt><dd>Nối 5 · 9 × 9 · không phải OTTv2</dd><dt>Giới hạn giải</dt><dd>Chưa chốt. Chưa tính % ngân sách.</dd></dl><details><summary>Hash để chạy lại đúng bản</summary><p>Source Python SHA-256</p><code>${report.source_hashes.bot_python_sha256}</code><p>Bộ fixture SHA-256</p><code>${report.suite_sha256}</code></details></section>
  <section class="panel bench-card"><h3>Đọc kết quả thế nào?</h3><p>Median cho biết tốc độ thường gặp. P95 và max giúp tìm tình huống chậm bất thường.</p><p>Trên server, cần so p95/max với giới hạn mỗi lượt và đo thêm RAM của cả sandbox. Bộ test cần có khai cuộc, trung cuộc, cuối cuộc và trạng thái nhiều nhánh.</p><div class="info-note">${icon('info')}Bot nhanh không đồng nghĩa bot mạnh. Benchmark tài nguyên tách khỏi điểm đấu thử.</div></section></aside></div>`;
}
export function exportBenchmark(download){download('uet-arena-LAB-20261010-01.json',JSON.stringify(report,null,2),'application/json');}
